class Stack:
    """A simple LIFO stack backed by a Python list."""

    def __init__(self):
        self._items = []

    def push(self, x):
        """Push x onto the top of the stack."""
        self._items.append(x)

    def pop(self):
        """Remove and return the top item. Raises IndexError if the stack is empty."""
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):
        """Return the top item without removing it. Raises IndexError if the stack is empty."""
        if not self._items:
            raise IndexError("peek from empty stack")
        return self._items[-1]

    def is_empty(self):
        """Return True if the stack has no items."""
        return not self._items

    def size(self):
        """Return the number of items in the stack."""
        return len(self._items)

