from typing import Callable, Dict, List

from events import Event

Handler = Callable[[Event], None]


class EventBus:
    """In-memory publish/subscribe event bus."""

    def __init__(self) -> None:
        self._handlers: Dict[str, List[Handler]] = {}

    def subscribe(self, name: str, handler: Handler) -> None:
        """Register handler for events named `name`. Handlers run in subscription order."""
        self._handlers.setdefault(name, []).append(handler)

    def unsubscribe(self, name: str, handler: Handler) -> None:
        """Remove the earliest subscription of handler for `name`.

        If the handler is not subscribed, this does nothing.
        """
        handlers = self._handlers.get(name)
        if not handlers:
            return
        try:
            handlers.remove(handler)
        except ValueError:
            return
        if not handlers:
            del self._handlers[name]

    def publish(self, event: Event) -> None:
        """Call every handler subscribed to event.name with the event, in order.

        Publishing an event with no subscribers does nothing.
        """
        # Copy the list so handlers may subscribe/unsubscribe during dispatch.
        for handler in list(self._handlers.get(event.name, ())):
            handler(event)

