"""Command registry: register handlers by name and dispatch to them."""

_REGISTRY = {}


class UnknownCommandError(KeyError, ValueError):
    """Raised for unregistered commands.

    Subclasses KeyError (the registry contract) and ValueError (what
    handlers.run() raised before the refactor), so existing callers that
    catch ValueError keep working.
    """


def register(name):
    """Decorator that registers ``func`` as the handler for command ``name``."""
    if not isinstance(name, str):
        raise TypeError("command name must be a str, got %r" % (name,))

    def decorator(func):
        existing = _REGISTRY.get(name)
        if existing is not None and existing is not func:
            raise ValueError("command already registered: " + name)
        _REGISTRY[name] = func
        return func

    return decorator


def dispatch(name, value):
    """Call the handler registered for ``name`` with ``value``."""
    try:
        handler = _REGISTRY[name]
    except (KeyError, TypeError):
        raise UnknownCommandError("unknown command: " + str(name)) from None
    return handler(value)

