def two_sum(nums, target):
    """Return (i, j) with i < j such that nums[i] + nums[j] == target, or None.

    Uses a single pass with a hash map of value -> index, giving O(n) time
    and O(n) extra space. An element is never paired with itself because
    each value's complement is looked up before that value is recorded.
    """
    seen = {}
    for j, value in enumerate(nums):
        complement = target - value
        if complement in seen:
            return (seen[complement], j)
        if value not in seen:
            seen[value] = j
    return None

