_registry = {}


def register(name):
    """Decorator to register a command handler by name."""
    def decorator(func):
        _registry[name] = func
        return func
    return decorator


def dispatch(name, value):
    """Dispatch a command by name with the given value.

    Raises KeyError if the command name was never registered.
    """
    if name not in _registry:
        raise KeyError(f"unknown command: {name}")
    return _registry[name](value)

