import pytest
from validator import validate


def test_valid_form():
    """Test that a fully valid form returns no errors."""
    form = {
        "email": "user@example.com",
        "age": 25,
        "username": "john_doe"
    }
    errors = validate(form)
    assert errors == []


def test_missing_email():
    """Test that a missing email returns an error."""
    form = {
        "email": "",
        "age": 25,
        "username": "john_doe"
    }
    errors = validate(form)
    assert "invalid email" in errors


def test_email_without_at_symbol():
    """Test that an email without '@' returns an error."""
    form = {
        "email": "userexample.com",
        "age": 25,
        "username": "john_doe"
    }
    errors = validate(form)
    assert "invalid email" in errors


def test_age_below_18():
    """Test that an age below 18 returns an error."""
    form = {
        "email": "user@example.com",
        "age": 17,
        "username": "john_doe"
    }
    errors = validate(form)
    assert "must be 18 or older" in errors


def test_non_integer_age():
    """Test that a non-integer age returns an error."""
    form = {
        "email": "user@example.com",
        "age": "25",
        "username": "john_doe"
    }
    errors = validate(form)
    assert "must be 18 or older" in errors


def test_username_too_short():
    """Test that a username shorter than 3 characters returns an error."""
    form = {
        "email": "user@example.com",
        "age": 25,
        "username": "ab"
    }
    errors = validate(form)
    assert "username too short" in errors
